-- ds_decisions — GENERATED by tools/build_production.py from tools/dashboard_datasets.py.
-- Paste into the dashboard's Data tab as a dataset named ds_decisions.
-- The audit register, one row per event. Triage: Decision log.

SELECT d.event_ts, d.cohort_id, c.severity, c.business_domain,
       regexp_extract(c.root_cause_hypothesis, '^[^.:]*', 0)                    AS claim,
       d.event_seq, d.event_type, d.decision, d.actor_display_name, d.actor_identity,
       d.actor_source, d.reason, d.review_by_date, d.approver_ordinal,
       d.violations_before, d.violations_after, d.verification_passed
FROM   sdpt_data_trnf.udp_brnz.dq_results_disposition d
JOIN   sdpt_data_trnf.udp_brnz.dq_results_v_cohort_for_bi c ON c.cohort_id = d.cohort_id
